```matlab
%% ====================================================================
% 场景：并联APF补偿三相不控整流负载
% 采用 ip-iq 法实时检测谐波指令，理想补偿后电网电流应恢复为正弦基波
% ====================================================================

clear; clc; close all;

%% 1. 场景参数设置（对应假想负载与电网）
f = 50; % 电网基频 [Hz]
fs = 10000; % 采样频率 [Hz]
T = 0.2; % 仿真时长 [s]
t = 0:1/fs:T-1/fs; % 时间轴
omega = 2*pi*f; % 角频率
N = length(t);

% --- 谐波制造：模拟不控整流特征参数 ---
I1m = 10; % 基波电流幅值 [A]
harm_order = [5, 7, 11, 13]; % 特征谐波次数
harm_amp_ratio = [0.20, 0.14, 0.09, 0.07]; % 相对基波幅值比

% 三相基波初相角
phi_1 = [0, -2*pi/3, 2*pi/3]; % A,B,C

% --- 合成三相负载电流 iL_abc（畸变严重）---
iLa = I1m * cos(omega*t + phi_1(1));
iLb = I1m * cos(omega*t + phi_1(2));
iLc = I1m * cos(omega*t + phi_1(3));
for k = 1:length(harm_order)
n = harm_order(k);
amp = I1m * harm_amp_ratio(k);
iLa = iLa + amp * cos(n*omega*t + phi_1(1));
iLb = iLb + amp * cos(n*omega*t + phi_1(2));
iLc = iLc + amp * cos(n*omega*t + phi_1(3));
end

% --- 电网电压（理想三相对称，仅用于PLL）---
Vm = 311; % 相电压幅值 [V]
va = Vm * cos(omega*t);
vb = Vm * cos(omega*t - 2*pi/3);
vc = Vm * cos(omega*t + 2*pi/3);

%% 2. 锁相环（SRF-PLL）提取电网电压相位 θ

% 采用基于同步参考坐标系的PLL，从三相电压中实时提取相位角
theta = zeros(1,N);
phi_pll = 0; % 初始相位
freq_est = f; % 估算频率初值

% PLL的PI控制器参数
Kp_pll = 0.8; Ki_pll = 20;
integral_pll = 0;
v_alpha = zeros(1,N); v_beta = zeros(1,N);
v_d = zeros(1,N); v_q = zeros(1,N);
for n = 1:N

% Clarke 变换 (等幅值)
v_alpha(n) = (2/3)*va(n) - (1/3)*vb(n) - (1/3)*vc(n);
v_beta(n) = (1/sqrt(3))*(vb(n) - vc(n));

% Park 变换（使用当前 PLL 相位）
v_d(n) = v_alpha(n)*cos(phi_pll) + v_beta(n)*sin(phi_pll);
v_q(n) = -v_alpha(n)*sin(phi_pll) + v_beta(n)*cos(phi_pll);

% 鉴相：v_q 作为相位误差信号
error_pll = v_q(n);

% PI 控制器（环路滤波器）
integral_pll = integral_pll + error_pll / fs;
pi_out = Kp_pll * error_pll + Ki_pll * integral_pll;

% 频率更新与相位累加（VCO/NCO）

freq_est = f + pi_out;
if n > 1
phi_pll = phi_pll + 2*pi*freq_est/fs;
end
phi_pll = mod(phi_pll, 2*pi);
theta(n) = phi_pll;
end

%% 3. ip-iq 谐波检测核心算法

% 预分配内存

i_alpha = zeros(1,N); i_beta = zeros(1,N);
ip = zeros(1,N); iq = zeros(1,N);
ip_dc = zeros(1,N); iq_dc = zeros(1,N); % 滤波后的直流分量
i_alpha_f = zeros(1,N); i_beta_f = zeros(1,N);
iaf = zeros(1,N); ibf = zeros(1,N); icf = zeros(1,N); % 重建基波
iah_ref = zeros(1,N); ibh_ref = zeros(1,N); ich_ref = zeros(1,N);% 谐波指令

% 设计低通滤波器（2阶Butterworth，截止频率20Hz）

fc = 20;
[b,a] = butter(2, fc/(fs/2), 'low');

% 滤波器状态变量，用于逐点滤波

z_ip = zeros(2,1); z_iq = zeros(2,1);
for n = 1:N

% 3.1 Clarke 变换

i_alpha(n) = (2/3)*iLa(n) - (1/3)*iLb(n) - (1/3)*iLc(n);
i_beta(n) = (1/sqrt(3))*(iLb(n) - iLc(n));

% 3.2 Park 变换（使用 PLL 输出的 θ）

ip(n) = i_alpha(n)*cos(theta(n)) + i_beta(n)*sin(theta(n));
iq(n) = -i_alpha(n)*sin(theta(n)) + i_beta(n)*cos(theta(n));

% 3.3 LPF 提取直流分量（代表基波有功和无功）

[ip_dc(n), z_ip] = filter(b, a, ip(n), z_ip);
[iq_dc(n), z_iq] = filter(b, a, iq(n), z_iq);

% 3.4 逆Park变换：直流 -> 两相静止基波

i_alpha_f(n) = ip_dc(n)*cos(theta(n)) - iq_dc(n)*sin(theta(n));
i_beta_f(n) = ip_dc(n)*sin(theta(n)) + iq_dc(n)*cos(theta(n));

% 3.5 逆Clarke变换：两相静止 -> 三相基波电流

iaf(n) = i_alpha_f(n);
ibf(n) = -1/2 * i_alpha_f(n) + sqrt(3)/2 * i_beta_f(n);
icf(n) = -1/2 * i_alpha_f(n) - sqrt(3)/2 * i_beta_f(n);

% 3.6 谐波补偿指令 = 负载电流 - 基波电流

iah_ref(n) = iLa(n) - iaf(n);
ibh_ref(n) = iLb(n) - ibf(n);
ich_ref(n) = iLc(n) - icf(n);
end

%% 4. 理想补偿效果：APF注入谐波指令，电网电流 = 负载电流 - 指令

is_a = iLa - iah_ref; % 即等于提取的基波 iaf
is_b = iLb - ibh_ref;
is_c = iLc - ich_ref;

%% 5. 结果评估与可视化

% 计算稳态THD（截取0.1s之后避免滤波器初始瞬态）
n_start = round(0.1*fs);
idx = n_start:N;
thd_iLa = compute_thd(iLa(idx), f, fs);
thd_is = compute_thd(is_a(idx), f, fs);
fprintf('负载电流 A 相 THD = %.2f%%\n', thd_iLa*100);
fprintf('补偿后电网电流 A 相 THD = %.2f%%\n', thd_is*100);

% ---------- 绘制波形 ----------
figure('Name','A相电流波形与检测结果','Position',[100,100,900,600]);
subplot(4,1,1); plot(t, iLa,'b'); ylabel('i_{La} (A)');
title('A 相负载电流（严重畸变）'); grid on; xlim([0 T]);
subplot(4,1,2); plot(t, iaf,'r','LineWidth',1.2); ylabel('i_{af} (A)');
title('ip-iq 法提取的基波电流'); grid on; xlim([0 T]);
subplot(4,1,3); plot(t, iah_ref,'m'); ylabel('i_{ah}^* (A)');
title('谐波补偿指令（要注入的电流）'); grid on; xlim([0 T]);
subplot(4,1,4); plot(t, is_a,'g','LineWidth',1.2); ylabel('i_{sa} (A)');
xlabel('时间 (s)'); title('补偿后电网电流（恢复正弦）'); grid on; xlim([0 T]);
% 显示 ip, iq 及其直流分量
figure('Name','旋转坐标系下的电流分量','Position',[100,100,800,400]);
subplot(2,1,1); plot(t, ip,'b', t, ip_dc,'r','LineWidth',1.2);
ylabel('i_p (A)'); legend('原始 i_p','直流 \bar{i}_p'); title('i_p 的直流提取'); grid on; xlim([0 T]);
subplot(2,1,2); plot(t, iq,'b', t, iq_dc,'r','LineWidth',1.2);
ylabel('i_q (A)'); legend('原始 i_q','直流 \bar{i}_q'); title('i_q 的直流提取'); grid on; xlim([0 T]);

%% 辅助函数：计算THD（基于FFT）
function THD = compute_thd(signal, fund_freq, fs)
L = length(signal);
N_cyc = floor(L * fund_freq / fs);
N_per = floor(fs / fund_freq);
if N_cyc < 1, THD = 0; return; end
seg = signal(1:N_cyc*N_per);
Y = fft(seg);
P2 = abs(Y/length(seg));
P1 = P2(1:floor(length(seg)/2)+1);
P1(2:end-1) = 2*P1(2:end-1);
f_ax = fs*(0:floor(length(seg)/2))/length(seg);
[~, idx_f] = min(abs(f_ax - fund_freq));
A_fund = P1(idx_f);
THD = sqrt(sum(P1.^2) - A_fund^2) / A_fund;
end
